<?php
// Temporary local-only SMTP form. Replace with authenticated admin settings before deployment.
if (!in_array($_SERVER['REMOTE_ADDR'] ?? '', ['127.0.0.1', '::1'], true)) { http_response_code(403); exit('Local setup only.'); }
session_start(); $_SESSION['smtp_csrf'] ??= bin2hex(random_bytes(32)); $notice = ''; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  if (!hash_equals($_SESSION['smtp_csrf'], $_POST['csrf'] ?? '')) $error = 'Invalid request.';
  else {
    $smtp = ['host'=>trim($_POST['host'] ?? ''), 'port'=>(int)($_POST['port'] ?? 587), 'username'=>trim($_POST['username'] ?? ''), 'password'=>(string)($_POST['password'] ?? ''), 'encryption'=>$_POST['encryption'] === 'ssl' ? 'ssl' : 'tls', 'from_address'=>trim($_POST['from_address'] ?? ''), 'from_name'=>trim($_POST['from_name'] ?? 'Flowwithlit')];
    if (!$smtp['host'] || !$smtp['username'] || !$smtp['password'] || !filter_var($smtp['from_address'], FILTER_VALIDATE_EMAIL)) $error = 'Please complete every required field.';
    else { file_put_contents(__DIR__ . '/../config/smtp.local.php', "<?php\nreturn " . var_export($smtp, true) . ";\n", LOCK_EX); $notice = 'Saved locally. Your password will not be displayed again.'; }
  }
}
